<script setup lang="ts">
import { computed,reactive,ref } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { useAuth } from '../stores/auth';
import { useUi } from '../stores/ui';
const route=useRoute(),router=useRouter(),auth=useAuth(),ui=useUi(),busy=ref(false);
const register=computed(()=>route.path==='/register'),form=reactive({name:'',email:'',password:'',password_confirmation:''});
async function submit(){busy.value=true;try{if(!auth.ready)await auth.load();await auth.submit(register.value?'register':'login',form);await router.push('/');}catch(e){ui.fail(e);}finally{busy.value=false;}}
</script>
<template><div class="auth-layout"><section class="auth-story"><div class="brand text-white"><span class="brand-icon"><v-icon icon="mdi-transit-connection-variant"/></span>TaskFlow.</div><div class="auth-story-content"><div class="eyebrow">VIENA KOMANDA. VIENS VIRZIENS.</div><h1>No labas idejas<br>līdz paveiktam<br><span>darbam.</span></h1><p>Projekti, uzdevumi un cilvēki vienuviet.<br>Mazāk jucekļa. Vairāk kopā paveiktā.</p><div class="auth-illustration"><div class="mini-task"><v-icon icon="mdi-check-circle" color="success"/> Ideja ir gatava <span>01</span></div><div class="mini-task offset"><v-icon icon="mdi-progress-clock" color="warning"/> Komanda ir procesā <span>02</span></div><div class="mini-task"><v-icon icon="mdi-flag-outline" color="primary"/> Nākamais mērķis — tavs <span>03</span></div></div></div><small>Radīts studentiem un mazām komandām.</small></section><section class="auth-form"><div class="auth-form-inner"><div class="eyebrow text-primary">SĀKAM DARBU</div><h2>{{register?'Izveido savu kontu':'Prieks tevi atkal redzēt'}}</h2><p class="text-medium-emphasis mb-8">{{register?'Tavs nākamais projekts sākas šeit.':'Piesakies un turpini iesākto.'}}</p><form @submit.prevent="submit"><v-text-field v-if="register" v-model="form.name" label="Vārds un uzvārds" autocomplete="name" required maxlength="100"/><v-text-field v-model="form.email" label="E-pasts" type="email" autocomplete="email" required maxlength="254"/><v-text-field v-model="form.password" label="Parole" type="password" :autocomplete="register?'new-password':'current-password'" required :minlength="register?8:undefined" :hint="register?'Vismaz 8 rakstzīmes':''"/><v-text-field v-if="register" v-model="form.password_confirmation" label="Atkārtota parole" type="password" autocomplete="new-password" required/><v-btn type="submit" color="primary" block size="large" class="mt-3" :loading="busy">{{register?'Izveidot kontu':'Pieteikties'}}<v-icon icon="mdi-arrow-right" end/></v-btn></form><p class="text-center mt-7 text-body-2">{{register?'Jau ir konts?':'Vēl nav konta?'}} <router-link :to="register?'/login':'/register'">{{register?'Piesakies':'Reģistrējies'}}</router-link></p></div></section></div></template>

